import { after } from 'next/server'
import { headers } from 'next/headers'

async function logPageView(event: {
  path: string
  userAgent: string
  timestamp: number
}) {
  try {
    await fetch('https://analytics.example.com/pageview', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(event),
      keepalive: true,
    })
  } catch (err) {
    console.error('[analytics] failed to log pageview', err)
  }
}

export default async function Home() {
  const requestHeaders = await headers()
  const event = {
    path: requestHeaders.get('x-pathname') ?? '/',
    userAgent: requestHeaders.get('user-agent') ?? 'unknown',
    timestamp: Date.now(),
  }

  after(async () => {
    await logPageView(event)
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn&apos;t block the response.</p>
    </main>
  )
}
